// 传闻 · 轶事 批量生成脚本 — 程序化生成 44 篇传闻(TALES_EXT) + 400 篇轶事(QUIRKS)
// 运行：node scripts/gen_tales.mjs
// 产出：src/game/data/tales_ext.js（导出 TALES_EXT 与 QUIRKS）
import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const __dir = dirname(fileURLToPath(import.meta.url))
const base = join(__dir, '..', 'src')
const d = (p) => join(base, p)
const data = (p) => join(base, 'game', 'data', p)

async function load(path) {
  try { return await import('file:///' + d(path).replace(/\\/g, '/')) } catch { return null }
}

// ITEMS 与 itemName
const itemsModule = await load('game/data/items.js')
const getItem = itemsModule?.getItem ?? (() => null)
const itemName = itemsModule?.itemName ?? ((id) => id)

// 采集目标（itemId, name, reqLevel）
const TARGETS = []
// 按采集技能分组的真实目标（供采集子子类轶事，贴合每技能机制）
const GATHER_BY_SKILL = {}
async function addTargets(mod, arrayName, skillId) {
  const m = await load(mod)
  if (!m || !m[arrayName]) return
  if (!GATHER_BY_SKILL[skillId]) GATHER_BY_SKILL[skillId] = []
  for (const t of m[arrayName]) {
    const item = { id: t.itemId, name: itemName(t.itemId), lvl: t.reqLevel ?? t.req ?? 1 }
    GATHER_BY_SKILL[skillId].push(item)
    TARGETS.push(item)
  }
}
await addTargets('game/skills/ForagingSkill.js', 'FORAGING_TARGETS', 'foraging')
await addTargets('game/skills/FishingSkill.js', 'FISHING_TARGETS', 'fishing')
await addTargets('game/skills/HuntingSkill.js', 'HUNTING_TARGETS', 'hunting')
await addTargets('game/skills/ExcavationSkill.js', 'EXCAVATION_TARGETS', 'excavation')
await addTargets('game/skills/FarmingSkill.js', 'CROPS', 'farming')
for (const [mod, key, skillId] of [['game/data/expansion1.js', 'GATHERING_EXT', null], ['game/data/expansion2.js', 'GATHERING_EXT2', null]]) {
  const m = await load(mod)
  if (!m || !m[key]) continue
  for (const [sk, list] of Object.entries(m[key])) {
    const target = GATHER_BY_SKILL[sk] ?? (GATHER_BY_SKILL[sk] = [])
    for (const t of list) {
      const item = { id: t.itemId, name: itemName(t.itemId), lvl: t.reqLevel ?? 1 }
      target.push(item); TARGETS.push(item)
    }
  }
}

// 制作配方输出
const RECIPES = []
// 按制作技能分组的真实配方产物（供制作子子类轶事）
const RECIPE_BY_SKILL = {}
async function addRecipes(mod, arrayName, skillId) {
  const m = await load(mod)
  if (!m || !m[arrayName]) return
  if (!RECIPE_BY_SKILL[skillId]) RECIPE_BY_SKILL[skillId] = []
  for (const r of m[arrayName]) {
    const item = { id: r.output?.itemId ?? r.itemId, name: itemName(r.output?.itemId ?? r.itemId), lvl: r.reqLevel ?? 1 }
    RECIPE_BY_SKILL[skillId].push(item)
    RECIPES.push(item)
  }
}
await addRecipes('game/skills/CookingSkill.js', 'COOKING_RECIPES', 'cooking')
await addRecipes('game/skills/BakingSkill.js', 'BAKING_RECIPES', 'baking')
await addRecipes('game/skills/PreservingSkill.js', 'PRESERVING_RECIPES', 'preserving')
await addRecipes('game/skills/BrewingSkill.js', 'BREWING_RECIPES', 'brewing')
await addRecipes('game/skills/SpiceMixingSkill.js', 'SPICE_RECIPES', 'spiceMixing')
await addRecipes('game/skills/CraftsmithingSkill.js', 'SMITHING_RECIPES', 'craftsmithing')
for (const [mod, key] of [['game/data/expansion1.js', 'PRODUCTION_EXT'], ['game/data/expansion2.js', 'PRODUCTION_EXT2']]) {
  const m = await load(mod)
  if (!m || !m[key]) continue
  for (const [sk, list] of Object.entries(m[key])) {
    if (!RECIPE_BY_SKILL[sk]) RECIPE_BY_SKILL[sk] = []
    for (const r of list) {
      const item = { id: r.output?.itemId ?? r.itemId, name: itemName(r.output?.itemId ?? r.itemId), lvl: r.reqLevel ?? 1 }
      RECIPE_BY_SKILL[sk].push(item); RECIPES.push(item)
    }
  }
}
for (const [mod, key] of [['game/data/expansion1.js', 'SMITHING_EXT'], ['game/data/expansion2.js', 'SMITHING_EXT2'], ['game/data/expansion1.js', 'PRESERVE_EXT'], ['game/data/expansion2.js', 'PRESERVE_EXT2']]) {
  const m = await load(mod)
  if (!m || !m[key]) continue
  for (const r of m[key]) {
    const item = { id: r.output?.itemId ?? r.itemId, name: itemName(r.output?.itemId ?? r.itemId), lvl: r.reqLevel ?? 1 }
    RECIPES.push(item)
    // 按配方 id 前缀/归属难以精确，暂归入默认制作组（后续手工调整）
  }
}

// BOSS 名
const BOSSES = []
{
  const m = await load('game/data/combat.js')
  if (m?.COMBAT_BOSSES) for (const b of m.COMBAT_BOSSES) BOSSES.push(b.name)
  const e1 = await load('game/data/expansion1.js')
  if (e1?.BOSS_EXT) for (const b of e1.BOSS_EXT) BOSSES.push(b.name ?? b)
  const e2 = await load('game/data/expansion2.js')
  if (e2?.BOSS_EXT2) for (const b of e2.BOSS_EXT2) BOSSES.push(b.name ?? b)
}

// 对决·战斗：所有敌人（普通对手 + 首领）单独计为轶事目标
const ALL_ENEMIES = []
{
  const m = await load('game/data/combat.js')
  const seen = new Set()
  const pushName = (name) => { if (name && !seen.has(name)) { seen.add(name); ALL_ENEMIES.push(name) } }
  if (m?.COMBAT_REGIONS) for (const r of m.COMBAT_REGIONS) for (const o of (r.opponents ?? [])) pushName(o.name)
  for (const b of BOSSES) pushName(b)
}

// 技能名（用于轶事正文）
const skillModule = await load('game/data/skills.js')
const SKILL_DEFS = skillModule?.SKILL_DEFS ?? {}
const skillName = (id) => SKILL_DEFS[id]?.name ?? id

// 辅助类轶事可计数的真实动作/产物（探索成功 + 保鲜/食灵配方输出）
const SUPPORT_ACTIONS = [{ key: 'explore', name: '探索秘境' }]
async function addSupportActions(mod, arrayName) {
  const m = await load(mod)
  if (!m || !m[arrayName]) return
  for (const r of m[arrayName]) {
    const out = r.output?.itemId ?? r.itemId
    SUPPORT_ACTIONS.push({ key: out, name: itemName(out) })
  }
}
await addSupportActions('game/skills/PreservationSkill.js', 'PRESERVATION_RECIPES')
await addSupportActions('game/skills/SpiritSummoningSkill.js', 'SPIRIT_RECIPES')

