  combatScholar: [['纸上谈兵', '肚里的兵法，落在灶上。'], ['兵法入厨', '进退有据，攻守兼备。'], ['斗阵了然', '对手出招，心里有数。'], ['谋定后动', '未出手先算三步。'], ['攻守有据', '守得稳，攻得准。'], ['战学合一', '学问与刀，合为一体。'], ['以谋制胜', '不靠蛮力，靠章法。']],
