  swiftProwess: [['身手如风', '身法轻灵，风也追不上。'], ['武艺轻灵', '手上功夫，处处利落。'], ['快手生风', '手起刀落，带起一阵风。'], ['身法飘忽', '看似东，实到西。'], ['拳脚带风', '一动就是满室风。'], ['利落干练', '干净利落，毫不拖泥。'], ['风过无痕', '做完就走，了无痕迹。']],
  aoji_secret_knife: [['秘刀藏锋', '刀藏在影里，一露即收。'], ['刀下无声', '出刀无声，落刀无痕。'], ['寒刃出鞘', '寒光一闪，菜已分成。'], ['刀走玄机', '刀路暗藏机锋。'], ['锋芒暗藏', '锋芒不露，刀刃却利。'], ['刃秘于心', '刀的诀窍，记在心里。'], ['一刀破局', '乱局之中，一刀定音。']],
  aoji_secret_plating: [['盘中见功夫', '菜入盘，功夫立现。'], ['摆盘如画', '一盘菜，一幅画。'], ['一碟成景', '碟中自成一方天地。'], ['食器合璧', '器与菜，相得益彰。'], ['排盘有法', '甚么位置，都有讲究。'], ['如数家珍', '盘中的物，摆得妥帖。'], ['碟中乾坤', '小碟里藏着大乾坤。']],
  aoji_secret_flavor: [['味藏方寸', '滋味藏在分寸之间。'], ['一口入魂', '一口下去，魂都醒了。'], ['风味暗涌', '味道在嘴里慢慢涌开。'], ['滋味出乎意料', '尝之前想不到的味道。'], ['暗香浮动', '闻着不显，吃着最香。'], ['余味悠长', '吃完了，味还在。'], ['味里玄机', '这味道，另有门道。']],
  aoji_perfect_heat: [['火候入微', '火大势微，拿捏到毫厘。'], ['一火定味', '火对了，味就对了。'], ['火到即收', '火候一到，即刻收勺。'], ['文武兼施', '文火武火，交替自如。'], ['炉火纯青', '灶火炼到青，是火功。'], ['火里见真章', '真厨艺，都在火上。'], ['火喉精绝', '一喉火，唱出好味。']],
  aoji_wind_step: [['行步带风', '一步踏风，身如轻燕。'], ['踏风行', '踏着风走。'], ['疾步无声', '快得听不见脚步。'], ['风行水上', '行如风过水面。'], ['步履如风', '腿脚利落，风也是伴。'], ['快足生烟', '快得脚底生烟。'], ['风过留痕', '风虽过，痕还在。']],
  aoji_iron_gut2: [['铜胃铁肠', '再硬的菜也能容。'], ['百味不惧', '什么味都不怕。'], ['海胃吞川', '胃像海，吞得下山川。'], ['铁肚能容', '肚大能容，容得百味。'], ['千食不惊', '千顿下肚，眉头不皱。'], ['大胃如鼎', '胃如鼎，来者不拒。'], ['食量惊人', '吃得下，才是真本事。']],
  aoji_harvest_feast: [['丰年宴', '丰年的一桌，最是热闹。'], ['满仓席', '仓里满了，席也就开了。'], ['谷满桌', '新谷上桌，粒粒欢喜。'], ['岁熟宴', '岁岁熟，年年宴。'], ['丰收之馔', '把丰收做成菜。'], ['仓廪开宴', '仓廪盈，宴席开。'], ['五谷为馔', '五谷之香，皆成菜肴。']],
  aoji_knowledge_spring: [['学如泉涌', '学问像泉，活活涌出。'], ['知识活水', '知识是不竭的活水。'], ['博泉满溢', '满腹学问，如泉满溢。'], ['学脉润身', '读书之脉，润着身心。'], ['智泉常涌', '智慧之泉，从不停。'], ['书海饮泉', '在书海里舀一瓢。'], ['文思如泉', '文思如泉涌，落笔即章。']],
  aoji_soul_of_food: [['菜有魂', '一道菜，是有魂的。'], ['食灵入馔', '食灵悄悄住进菜里。'], ['菜魂不散', '菜冷了，魂还在。'], ['烹者与魂', '下厨的人与菜魂相通。'], ['味魂合一', '味与魂，合在一处。'], ['菜中气脉', '菜里有它的气脉。'], ['魂在锅底', '好菜的魂，留在锅底。']],
  aoji_berserk: [['灶火狂', '火一旺，心也狂。'], ['狠下重手', '这一勺，下得够重。'], ['爆炒如雷', '爆炒的响，像打雷。'], ['火气冲天', '灶火直冲天灵盖。'], ['猛火攻', '猛火猛攻，毫不留情。'], ['一炒惊雷', '一锅下去，噼啪如雷。'], ['烈性掌灶', '烈性子，掌得住烈火。']],
  aoji2_blade_tide: [['刀如潮', '刀起刀落，如潮水。'], ['刃浪层叠', '刀刃一层层，像浪。'], ['刀潮涌', '刀锋如潮，涌上来。'], ['刀刃如涛', '刀光似涛，一浪接一浪。'], ['千刃齐落', '千刀齐下，利落整齐。'], ['刀风卷', '刀风一卷，菜已切好。'], ['锋芒如潮', '锋芒荡荡，如潮拍岸。']],
  aoji2_plate_feast: [['盘满盛宴', '一满盘，便是一席。'], ['一盘乾坤', '盘中自有天地。'], ['盘中盛事', '盘里的菜，是件盛事。'], ['满碟之宴', '碟碟相叠，热闹非凡。'], ['菜登盘即席', '菜一入盘，即成一席。'], ['盘中山海', '盘里装下山与海。'], ['碟宴生辉', '碟碟生辉，满目琳琅。']],
