  aoji2_iron_wall: [['坚壁守味', '守住味道，寸步不让。'], ['壁立护心', '如壁护心，稳当。'], ['金汤玉壁', '金汤玉壁，铁桶一般。'], ['守如磐石', '守着本味，一动不动。'], ['壁厚难破', '壁再厚，味也难破。'], ['护味成城', '护味如护城。'], ['铁壁不移', '铁壁立定，雷打不动。']],
  aoji2_swift_thunder: [['迅雷之势', '快如迅雷，势不可挡。'], ['快如雷鸣', '一动手，像打了雷。'], ['电光火石', '转瞬之间，菜已下锅。'], ['瞬息而至', '眨眼就到。'], ['雷动风随', '雷声一动，风也跟随。'], ['疾雷不及掩耳', '快得掩不了耳。'], ['快得惊人', '这速度，惊到人。']],
