  aoji2_grain_abund: [['谷粒满仓', '谷粒堆得仓都满。'], ['禾丰岁稔', '禾苗丰，年岁稔。'], ['稼穑大成', '一年耕作，有了大成。'], ['五谷盈仓', '五谷收满，盈仓之喜。'], ['仓虞充实', '仓廪充实，心也踏实。'], ['年丰食足', '年景好，食无忧。'], ['谷香盈野', '田野里都是谷香。']],
