// BOSS/对手文本
function combatItemAt(i) {
  const arr = BOSSES.filter((x) => typeof x === 'string')
  if (!arr.length) return '擂台宿敌'
  return arr[i % arr.length]
}
const pick = (arr, i) => arr[i % arr.length]

