const QUIRKS = []
let qn = 1
// 生成「具体要做什么」的需求描述（needText），供故事页未解锁卡片显示
const NEED_ACTION = {
  gather: { foraging: '采摘', fishing: '钓到', hunting: '捕获', excavation: '挖到', farming: '收获' },
  craft: { cooking: '烹饪', baking: '烘焙', preserving: '腌制', brewing: '调酒', spiceMixing: '调料调配', craftsmithing: '厨具锻造' },
  support: { gastronomy: '激活美食奥义', preservation: '食材保鲜制作', exploration: '美食探索成功' },
}
// 鼓励语三段组合池：16×16×16 = 4096 种 > 3588，按条目 index 唯一解码，保证每条轶事鼓励语互不相同
const FLAVOR_A = ['山野把', '炉火将', '时间把', '大地以', '旧日把', '风将', '雨把', '晨光把', '老厨以', '灶前把', '旅途把', '灯火将', '海上把', '林间把', '雪夜把', '故乡把']
const FLAVOR_B = ['每一味都收', '新鲜的滋味', '最真的鲜', '那份热忱', '光阴的馈赠', '食材的魂魄', '熟悉的老味道', '反复练就的手艺', '最朴素的鲜', '难忘的那一口', '藏着的匠心', '等待的意义', '相遇的缘分', '人间烟火气', '光阴的耐心', '寸寸初心']
const FLAVOR_C = ['留在锅气里了', '记得最牢', '落进汤里', '封存进酱缸', '写进了食谱', '藏进岁月', '端上案头', '融进炉火', '化作一餐', '都在其中', '温着人心', '从不辜负', '自有回响', '最是动人', '刚刚好', '才算圆满']
function makeFlavor(idx) {
  const a = idx % 16, b = Math.floor(idx / 16) % 16, c = Math.floor(idx / 256) % 16
  return FLAVOR_A[a] + FLAVOR_B[b] + '，' + FLAVOR_C[c]
}
let flavorTick = 0
function makeNeedText(kind, sub, itemName, need) {
  let action, unit = '次'
  if (kind === 'gather') { action = `${NEED_ACTION.gather[sub] ?? '获得'} ${itemName}`; unit = '次' }
  else if (kind === 'craft') { action = `${NEED_ACTION.craft[sub] ?? '制作'} ${itemName}`; unit = '份' }
  else if (kind === 'battle') action = `击败 ${itemName}`
  else if (kind === 'spirit') action = `召唤食灵 ${itemName}`
  else if (kind === 'support') { action = `${NEED_ACTION.support[sub] ?? '完成'}${itemName ? ' ' + itemName : ''}`; unit = sub === 'preservation' ? '份' : '次' }
  else return `达成对应进度 ${need}`
  return `${action} ${need} ${unit}`
}
// 鼓励语单独字段（未解锁卡单独一行显示，如「老槽里转过的味，都带了点回甘。」）
function pickFlavor(kind, overrideFlavor) {
  let f = overrideFlavor ?? makeFlavor(flavorTick++)
  if (f && !/[\u3002！？]$/.test(f)) f += '。'
  return f
}
// 给标题加一点故事感：在物品/目标名前加文学修饰词，保留类别前缀便于归类
const TITLE_ADJ = ['晨露未干的', '炉火正旺的', '深山采来的', '古法封存的', '月下初成', '雾里藏香的', '时光慢炖的', '灶前新得的', '风里带故事的', '灯火温柔时做成的']
function literary(name, i) {
  const adj = TITLE_ADJ[i % TITLE_ADJ.length]
  // 避免「晨露未干的 苹果精灵/学徒厨师」这类对名词略拗口，针对不同结尾微调
  const bare = name.replace(/（.+）$/, '')
  return `${adj}${bare}`
}
function pushQuirk(catKey, sub, subName, itemName, body, need, param, unlockKind, opts) {
  const kind = unlockKind ?? QUIRK_CATS[catKey]?.kind
  // 对手/食灵名本身已是故事化名词，不套「做成的」类修饰；opts 提供手工 title/flavor 时优先使用（去模板）
  const title = opts?.title ?? ((kind === 'battle' || kind === 'spirit' || kind === 'support') ? itemName : literary(itemName, qn))
  const needText = makeNeedText(kind, sub, itemName, need)
  const flavor = pickFlavor(kind, opts?.flavor)
  QUIRKS.push({ id: 'quirk_' + qn, cat: catKey, sub, subtitle: subName + '·' + title, unlock: { kind, sub, param, need, needText, flavor }, body })
  qn++
}

// 采集大类：按技能子子类各生成 200 篇，正文贴合该技能真实机制，need=采集次数（第 i 篇需 i+1 次）
for (const sub of GATHER_SUBS) {
  const items = sub.items()
  if (!items.length) continue
  const target = items.length > 200 ? items.length * 2 : 200
  const specCount = {}
  for (let i = 0; i < target; i++) {
    const item = items[i % items.length]
    const body = sub.bodies[i % sub.bodies.length].replaceAll('{x}', item.name)
    // 标题/鼓励语：优先该具体物品专属文案，缺省回退该类意象（贴合物品名，去模板）
    // 用「该物品出现次数」轮换变体，避免同物品的多个实例落到同一句
    const specific = ITEM_THEME[item.id]
    const cat = getItem(item.id)?.category ?? getItem(item.id)?.type
    const pool = specific && specific.length ? specific : CATEGORY_THEME[cat]
    let opt = undefined
    if (pool && pool.length) {
      const c = specCount[item.id] = (specCount[item.id] ?? 0) + 1
      const p = pool[(c - 1) % pool.length]
      opt = { title: p[0], flavor: p[1] }
    }
    pushQuirk('gather', sub.id, sub.name, item.name, body, i + 1, item.id, undefined, opt)
  }
}

// 制作大类：按技能子子类各生成 200 篇，贴合该制作技能真实机制，need=制作成功次数（第 i 篇需 i+1 次）
for (const sub of CRAFT_SUBS) {
  const items = sub.items()
  if (!items.length) continue
  // 若该子子类真实物品数 > 200，则每物品 2 篇 → 共物品数×2 篇
  const target = items.length > 200 ? items.length * 2 : 200
  const specCount = {}
  for (let i = 0; i < target; i++) {
    const item = items[i % items.length]
    const body = sub.bodies[i % sub.bodies.length].replaceAll('{x}', item.name)
    // 标题/鼓励语：优先该具体产物物品专属文案（同 gather 的 per-item 轮换）
    const specific = ITEM_THEME[item.id]
    let opt = undefined
    if (specific && specific.length) {
      const c = specCount[item.id] = (specCount[item.id] ?? 0) + 1
      const p = specific[(c - 1) % specific.length]
      opt = { title: p[0], flavor: p[1] }
    }
    pushQuirk('craft', sub.id, sub.name, item.name, body, i + 1, item.id, undefined, opt)
  }
}

// 对决·战斗：每敌人单独一篇；敌人总数 > 200 时每敌人 2 篇 → 共敌人×2 篇
{
  const battle = DUEL_SUBS.find((s) => s.id === 'battle')
  const items = battle.items()
  const n = items.length
  const target = n > 200 ? n * 2 : 200
  const specCount = {}
  for (let i = 0; i < target; i++) {
    const item = items[i % n]
    const body = battle.bodies[i % battle.bodies.length].replaceAll('{x}', item.name)
    const specific = ITEM_THEME[item.id]
    let opt = undefined
    if (specific && specific.length) {
      const c = specCount[item.id] = (specCount[item.id] ?? 0) + 1
      const p = specific[(c - 1) % specific.length]
      opt = { title: p[0], flavor: p[1] }
    }
    pushQuirk('combatWins', 'battle', '战斗', item.name, body, i + 1, item.id, 'battle', opt)
  }
  // 对决·食灵召唤：每食灵 200 篇（食灵数量不足则循环）
  const spirit = DUEL_SUBS.find((s) => s.id === 'spirit')
  const sitems = spirit.items()
  if (sitems.length) {
    const sspecCount = {}
    for (let i = 0; i < 200; i++) {
      const item = sitems[i % sitems.length]
      const body = spirit.bodies[i % spirit.bodies.length].replaceAll('{x}', item.name)
      const specific = ITEM_THEME[item.id]
      let opt = undefined
      if (specific && specific.length) {
        const c = sspecCount[item.id] = (sspecCount[item.id] ?? 0) + 1
        const p = specific[(c - 1) % specific.length]
        opt = { title: p[0], flavor: p[1] }
      }
      pushQuirk('combatWins', 'spirit', '食灵召唤', item.name, body, i + 1, item.id, 'spirit', opt)
    }
  }
}

