for (const sub of SUPPORT_SUBS) {
  const items = sub.items()
  if (!items.length) continue
  const target = items.length > 200 ? items.length * 2 : 200
  const specCount = {}
  for (let i = 0; i < target; i++) {
    const item = items[i % items.length]
    const body = sub.bodies[i % sub.bodies.length].replaceAll('{x}', item.name)
    // 美食知识(gastronomy)：按奥义 per-item 专属文案轮换；食材保鲜(preservation)用 PRESERVE_HAND 手工库
    let opt = undefined
    if (sub.id === 'preservation' && PRESERVE_HAND[i]) {
      opt = { title: PRESERVE_HAND[i][0], flavor: PRESERVE_HAND[i][1] }
    } else if (sub.id === 'exploration' && EXPLORE_THEME[i]) {
      opt = { title: EXPLORE_THEME[i][0], flavor: EXPLORE_THEME[i][1] }
    } else if (sub.id === 'gastronomy') {
      const specific = ITEM_THEME[item.id]
      if (specific && specific.length) {
        const c = specCount[item.id] = (specCount[item.id] ?? 0) + 1
        const p = specific[(c - 1) % specific.length]
        opt = { title: p[0], flavor: p[1] }
      }
    }
    pushQuirk('support', sub.id, sub.name, item.name, body, i + 1, item.id, undefined, opt)
  }
}

